PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account (id INTEGER PRIMARY KEY CHECK(id=1), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS challenges (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, code_hash TEXT NOT NULL, expires INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, created INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS patients (id TEXT PRIMARY KEY, cpf_hash TEXT NOT NULL UNIQUE, archived INTEGER NOT NULL DEFAULT 0, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS catalog (id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS packages (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS appointments (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES packages(id), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_versions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES appointments(id), created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clinical (id TEXT PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(id), created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clinical_versions (id TEXT PRIMARY KEY, clinical_id TEXT NOT NULL REFERENCES clinical(id), created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contracts (id TEXT PRIMARY KEY, package_id TEXT NOT NULL REFERENCES packages(id), version INTEGER NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL, UNIQUE(package_id,version));
CREATE TABLE IF NOT EXISTS signed_files (id TEXT PRIMARY KEY, contract_id TEXT NOT NULL REFERENCES contracts(id), body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id TEXT PRIMARY KEY, dedupe_key TEXT UNIQUE, created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ledger (id TEXT PRIMARY KEY, package_id TEXT REFERENCES packages(id), created_at TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, at TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations (key TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, response TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS packages_patient ON packages(patient_id);
CREATE INDEX IF NOT EXISTS clinical_patient ON clinical(patient_id);
INSERT OR IGNORE INTO migrations VALUES (1, datetime('now'));
